using System.Reflection;

var asm = typeof(Microsoft.Agents.AI.ChatClientAgent).Assembly;

void DumpType(Type t) {
    Console.WriteLine($"\n=== {t.Name} (Base: {t.BaseType?.Name}) ===");
    foreach (var c in t.GetConstructors(BindingFlags.Public | BindingFlags.Instance))
    {
        var parms = string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"  ctor({parms})");
    }
    foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
        Console.WriteLine($"  prop: {p.PropertyType.Name} {p.Name}");
    foreach (var m in t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly).Where(m => !m.IsSpecialName))
    {
        var parms = string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"  method: {m.ReturnType.Name} {m.Name}({parms})");
    }
}

DumpType(typeof(Microsoft.Agents.AI.ChatClientAgentSession));

// Check AgentRunOptions base
var runOptsBase = typeof(Microsoft.Agents.AI.ChatClientAgentRunOptions).BaseType!;
DumpType(runOptsBase);

// Check ChatResponse (return of RunAsync)
var meaiAsm = typeof(Microsoft.Extensions.AI.IChatClient).Assembly;
var chatResponseType = meaiAsm.GetExportedTypes().FirstOrDefault(t => t.Name == "ChatResponse");
if (chatResponseType != null) DumpType(chatResponseType);

// Check AIFunctionFactory for creating tools
var aiFuncFactory = meaiAsm.GetExportedTypes().FirstOrDefault(t => t.Name == "AIFunctionFactory");
if (aiFuncFactory != null) {
    Console.WriteLine($"\n=== {aiFuncFactory.Name} ===");
    foreach (var m in aiFuncFactory.GetMethods(BindingFlags.Public | BindingFlags.Static).Where(m => !m.IsSpecialName))
    {
        var parms = string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"  {m.ReturnType.Name} {m.Name}({parms})");
    }
}
EOF
